mapper.select:
SELECT d.id          AS id,
d.dept_name   AS deptName,
d.description AS description,
d.created_at  AS createdAt,
d.updated_at  AS updatedAt
FROM `dept` d
WHERE d.is_deleted = 0


    AND d.dept_name LIKE CONCAT('%', #{adminDeptQueryDTO.name}, '%')



    AND d.created_at  >=  #{adminDeptQueryDTO.createdAtStart}


    AND d.created_at  <=  #{adminDeptQueryDTO.createdAtEnd}



    AND d.updated_at  >=  #{adminDeptQueryDTO.updatedAtStart}


    AND d.updated_at  <=  #{adminDeptQueryDTO.updatedAtEnd}

ORDER BY d.created_at DESC
